  f(4, C1, 'Manchas de umidade', 'Áreas mais escuras ou amareladas, frequentemente com contornos irregulares.', ['Infiltração', 'Vazamento', 'Condensação', 'Umidade residual', 'Falhas externas'], ['Compare a mancha em dias secos e chuvosos', 'Observe teto, rodapé, tubulações e áreas molhadas próximas'], 'Não use apenas uma nova demão para esconder a mancha.', ['Identificar e eliminar a fonte', 'Aguardar a secagem', 'Avaliar necessidade de tratamento específico (fundo bloqueador)', 'Preparar a superfície', 'Repintar corretamente'], 'Faça inspeção prévia e registre manchas existentes antes de começar.', 'Manchas podem ser o reflexo visível de um problema de umidade ainda ativo.', 'amarelo', 6, ['mancha', 'amarelada', 'escura']);
  f(5, C1, 'Umidade ascendente por capilaridade', 'O defeito começa próximo ao piso e sobe gradualmente, com manchas, sais e perda de acabamento.', ['Ausência de barreira impermeável', 'Solo úmido', 'Falhas na fundação', 'Reboco em contato com umidade constante'], ['Altura do problema ao longo da parede', 'Presença de sais e reboco fofo', 'Histórico de umidade no rodapé e no piso adjacente'], 'Não raspe e repinte apenas a faixa inferior sem tratar a ascensão da umidade.', ['Confirmar a ascensão capilar', 'Melhorar a barreira contra umidade (impermeabilização)', 'Aguardar secagem', 'Remover partes contaminadas', 'Refazer preparo e acabamento'], 'Planeje barreiras e impermeabilização no encontro entre piso e parede.', 'Se a parede continuar puxando água do solo, o problema vai voltar.', 'vermelho', 7, ['rodapé', 'sobe', 'capilaridade', 'piso']);
  f(6, C1, 'Deterioração próxima a tubulações', 'O dano aparece perto de canos, registros ou pontos hidráulicos, com manchas, bolhas e pintura enfraquecida.', ['Vazamento oculto', 'Condensação em tubulações', 'Vedação deficiente', 'Infiltração em paredes hidráulicas'], ['Proximidade com pontos de água', 'Manchas concentradas ou recorrentes', 'Sinais de umidade do lado oposto da parede'], 'Não feche o serviço apenas refazendo a pintura se houver suspeita de vazamento.', ['Localizar a tubulação ou o ponto afetado', 'Eliminar vazamento ou condensação', 'Secar completamente a área', 'Remover partes comprometidas', 'Preparar e repintar'], 'Observe paredes hidráulicas com atenção e registre sinais antes da obra.', 'Danos próximos a tubulações geralmente indicam causa ativa e localizada.', 'vermelho', 8, ['vazamento', 'cano', 'banheiro', 'tubulação']);
  f(7, C1, 'Deterioração por chuva em fachadas', 'Áreas externas expostas à chuva com manchas escorridas, descascamento e desgaste da película.', ['Fissuras externas', 'Falhas em pingadeiras e rufos', 'Fachada muito exposta', 'Impermeabilização insuficiente'], ['Se o problema piora após chuva', 'Topo de muros, peitoris e juntas', 'Caminhos de escorrimento da água'], 'Não repinte a fachada sem corrigir os pontos de entrada e escorrimento da água.', ['Identificar os pontos de entrada da água', 'Corrigir fissuras, vedação ou arremates', 'Aguardar secagem da fachada', 'Preparar a base adequadamente', 'Repintar com sistema indicado para exterior'], 'Faça inspeção periódica de fachadas e arremates.', 'Em área externa, o acabamento só resiste quando a água deixa de entrar.', 'vermelho', 9, ['fachada', 'chuva', 'muro', 'escorrido']);

