  f(31, C5, 'Enrugamento', 'A película forma rugas, dobras ou aparência enrugada logo após a aplicação ou secagem inicial.', ['Camada muito espessa', 'Repintura prematura', 'Secagem superficial rápida', 'Incompatibilidade entre produtos'], ['Espessura aplicada', 'Tempo entre demãos', 'Sistema anterior', 'Condições de secagem'], 'Não aplique nova demão por cima tentando esconder a ruga.', ['Aguardar estabilização', 'Remover película defeituosa', 'Identificar o sistema existente', 'Corrigir espessura e intervalo', 'Reaplicar compatível'], 'Aplique camadas regulares e respeite secagem e compatibilidade.', 'Enrugamento normalmente indica reação, excesso de espessura ou repintura fora do tempo.', 'amarelo', 33, ['enrugou', 'ruga', 'dobra']);
