  f(33, C5, 'Repintura com baixa aderência', 'A tinta nova se desprende da antiga ao toque, à raspagem ou em testes simples.', ['Superfície brilhante', 'Falta de preparo', 'Sujeira', 'Incompatibilidade'], ['Aderência da pintura antiga', 'Tipo de acabamento', 'Existência de lixamento', 'Limpeza da superfície'], 'Não continue a repintura sem testar a aderência da base.', ['Testar a aderência', 'Preparar ou lixar a superfície', 'Remover áreas instáveis', 'Reaplicar sistema compatível'], 'Sempre teste a base antes de iniciar uma repintura completa.', 'A tinta nova pode estar boa, mas a película antiga pode estar fraca.', 'amarelo', 35, ['repintura', 'aderência']);
