  f(36, C5, 'Sangramento de pigmentos ou manchas', 'Manchas amareladas, escurecidas ou a cor antiga atravessam a nova pintura mesmo após novas demãos.', ['Pigmentos migrando', 'Contaminantes', 'Madeira ou tanino', 'Manchas antigas do substrato'], ['Origem da mancha', 'Recorrência', 'Tipo de base', 'Pontos localizados'], 'Não continue dando demãos sem tratar a origem da mancha.', ['Identificar a fonte', 'Limpar ou tratar quando possível', 'Aplicar fundo bloqueador/isolante apropriado', 'Repintar', 'Monitorar retorno'], 'Trate a origem e use fundo adequado ao contaminante.', 'Se a mancha migra pela tinta, mais demãos sozinhas raramente resolvem.', 'amarelo', 38, ['sangramento', 'mancha atravessa', 'amarela']);

  f(37, C6, 'Descascamento em madeira', 'Tinta ou verniz se solta em lascas, expondo fibras da madeira.', ['Umidade', 'Madeira mal preparada', 'Acabamento antigo fraco', 'Sistema inadequado'], ['Teor de umidade', 'Estado da madeira', 'Acabamento anterior', 'Áreas expostas ao clima'], 'Não lixe e repinte sem investigar a umidade da peça.', ['Eliminar a umidade', 'Remover acabamento solto', 'Preparar ou lixar', 'Corrigir a base (fundo)', 'Aplicar sistema adequado'], 'Madeira seca e bem preparada é essencial para aderência.', 'Se a madeira continua úmida, o descascamento tende a voltar.', 'amarelo', 39, ['madeira', 'verniz', 'lascas']);
  f(38, C6, 'Bolhas em madeira', 'Elevações ou bolhas sob a tinta ou verniz aplicado sobre a madeira.', ['Umidade interna', 'Aquecimento solar', 'Preparo deficiente', 'Sistema inadequado'], ['Exposição ao sol', 'Umidade da peça', 'Estado do filme', 'Localização das bolhas'], 'Não estoure e feche as bolhas sem corrigir a causa.', ['Investigar umidade ou calor', 'Remover partes comprometidas', 'Secar a madeira', 'Preparar a peça', 'Reaplicar o sistema adequado'], 'Respeite a preparação e as condições de uso da madeira.', 'Bolha em madeira costuma indicar umidade ou aquecimento sob a película.', 'amarelo', 40, ['madeira', 'bolha', 'sol']);
  f(39, C6, 'Manchas de tanino', 'Manchas amareladas ou amarronzadas atravessam o acabamento, especialmente em peças de madeira.', ['Substâncias naturais da madeira', 'Extração de taninos', 'Umidade', 'Falta de fundo isolante'], ['Tipo de madeira', 'Acabamento anterior', 'Recorrência da mancha'], 'Não tente esconder a mancha apenas com mais demãos.', ['Identificar a origem', 'Tratar ou secar a peça', 'Aplicar fundo isolante/bloqueador', 'Repintar'], 'Use preparação isolante compatível antes do acabamento.', 'Quando o tanino migra pela pintura, o bloqueio correto é essencial.', 'amarelo', 41, ['tanino', 'madeira', 'amarelada']);
  f(40, C6, 'Ferrugem atravessando a pintura', 'Pontos ou manchas alaranjadas aparecem através da película de pintura.', ['Corrosão não removida', 'Proteção insuficiente', 'Metal exposto', 'Falha do sistema anticorrosivo'], ['Extensão da ferrugem', 'Estado do metal', 'Primer utilizado', 'Pontos de umidade'], 'Não cubra a ferrugem sem tratar o metal corretamente.', ['Remover a corrosão', 'Preparar o metal', 'Aplicar proteção anticorrosiva (fundo)', 'Refazer o sistema', 'Repintar'], 'A preparação do metal e o primer correto são decisivos.', 'Ferrugem aparecendo pela tinta indica que a corrosão continua ativa.', 'vermelho', 42, ['ferrugem', 'alaranjado', 'metal', 'portão']);
