/* ───────────────────────── PRODUTOS DA CALCULADORA (rendimento típico) ───────────────────────── */
// Rendimento típico por EMBALAGEM e por DEMÃO (m²). São referências de mercado para ajudar quem está começando;
// o valor real está na embalagem de cada produto. O vendedor pode sobrescrever na calculadora.
CONTEUDO.rendimentos_tipicos = {
  'Tinta': { '18 L': '250 a 350 m² por demão (acrílica premium ~300; standard ~220)', '3,6 L': '50 a 70 m² por demão', '900 ml': '12 a 17 m² por demão', '16 L': '220 a 300 m² por demão', '3,2 L': '45 a 60 m² por demão' },
  'Massa corrida': { '25 Kg': '25 a 30 m² por demão (camada fina)', '18 Kg': '18 a 22 m² por demão', '15 Kg': '15 a 18 m² por demão', '3,6 Kg': '3,5 a 4,5 m² por demão', '1 Kg': '1 m² por demão' },
  'Massa acrílica': { '25 Kg': '22 a 28 m² por demão', '18 Kg': '16 a 20 m² por demão', '15 Kg': '13 a 17 m² por demão', '3,6 Kg': '3 a 4 m² por demão', '1 Kg': '1 m² por demão' },
  'Selador': { '18 L': '180 a 250 m² (1 demão)', '3,6 L': '36 a 50 m²', '900 ml': '9 a 12 m²' },
  'Fundo preparador': { '18 L': '140 a 200 m² (1 demão)', '3,6 L': '28 a 40 m²', '900 ml': '7 a 10 m²' },
  'Primer': { '3,6 L': '35 a 50 m² (1 demão)', '900 ml': '9 a 12 m²', '18 L': '180 a 250 m²' },
  'Textura': { '25 Kg': '12 a 20 m² (rolo) — 1 demão', '18 Kg': '9 a 14 m²', '15 Kg': '7 a 12 m²' },
  'Verniz': { '3,6 L': '40 a 50 m² por demão', '900 ml': '10 a 12 m² por demão' },
  'Esmalte': { '3,6 L': '40 a 55 m² por demão', '900 ml': '10 a 14 m² por demão', '18 L': '200 a 270 m² por demão' },
  'Outro': {},
};

/* ───────────────────────── BASE DE CONHECIMENTO (Assessor / chat) ───────────────────────── */
(function () {
  const KB = [];
  const add = (id, titulo, conteudo, tags) => KB.push({ id, titulo, conteudo: conteudo.trim(), tags: tags || [], ordem: KB.length + 1, ativo: true });

  add('kb_regra_ouro', 'Regra de ouro: não pinte o problema', `Tinta não corrige infiltração, umidade, reboco fraco, superfície soltando, gordura, mofo ativo, fissuras, poeira ou tinta antiga sem aderência. Antes de perguntar "qual tinta vou usar?", pergunte "essa superfície está pronta para receber pintura?". Sequência profissional: analisar → preparar → escolher → aplicar → conferir → entregar. Regra de bolso: superfície FIRME + LIMPA + SECA + PREPARADA = melhor base para o sistema de pintura.`, ['preparação', 'regra', 'retrabalho']);
  add('kb_tipos_tinta', 'Tipos de tinta e onde usar', `Látex PVA: só interiores secos (sala, quarto), menor lavabilidade, preço menor. Tinta acrílica: interior e exterior, lavável, mais resistente — é a indicação padrão para paredes. Acrílica premium: maior rendimento e cobertura, acabamento fosco/acetinado/semibrilho. Esmalte sintético (ou esmalte à base d'água): madeira e metal (portas, grades, portões, batentes), acabamento brilhante ou acetinado. Verniz/stain: madeira com aspecto natural; em exterior use com filtro solar. Tinta para piso: cimentados, quadras, garagens. Textura acrílica: fachadas e paredes com efeito, consome mais produto. Tinta epóxi: pisos industriais, azulejos e áreas de alto tráfego.`, ['tinta', 'látex', 'acrílica', 'esmalte', 'verniz', 'piso', 'textura', 'produto']);
  add('kb_acabamentos', 'Acabamentos: fosco, acetinado, semibrilho e brilhante', `Fosco: disfarça imperfeições, indicado para tetos e paredes com pequenas irregularidades; menos lavável. Acetinado: leve brilho e boa lavabilidade — salas, quartos, corredores. Semibrilho: alta lavabilidade — cozinhas, banheiros, áreas de serviço, corredores de muito toque. Brilhante: máxima resistência e limpeza, mais comum em esmalte (portas, metais). Quanto mais brilho, mais as imperfeições da parede aparecem — avise o cliente.`, ['acabamento', 'fosco', 'acetinado', 'semibrilho', 'brilhante']);
  add('kb_demaos_diluicao', 'Demãos, diluição e tempo de secagem', `Em geral: 2 a 3 demãos de tinta (3 quando a cor muda muito ou sobre superfície nova). Massa: 2 demãos finas, lixar entre elas. Selador/fundo: 1 demão. Diluição: NÃO existe diluição universal — leia a embalagem (tintas acrílicas costumam aceitar 10% a 20% de água na 1ª demão; esmalte sintético com aguarrás conforme o fabricante). Diluir "no olho" causa manchas e baixa cobertura. Respeite o intervalo entre demãos da embalagem (normalmente 4 horas para acrílica; esmalte sintético 8 a 12 horas); parede seca ao toque não significa pronta. Mais tinta numa demão NÃO substitui mais demãos.`, ['demão', 'demãos', 'diluição', 'secagem', 'intervalo', 'água']);
  add('kb_calculo', 'Como calcular a quantidade de tinta', `Área das paredes = perímetro (soma das larguras) × altura; teto = comprimento × largura. Desconte portas (~1,6 m² cada) e janelas (área de cada uma). Quantidade = área × número de demãos ÷ rendimento por demão. Rendimentos típicos por demão: acrílica premium 18 L ≈ 300 m² (standard ≈ 220 m²); 3,6 L ≈ 55 m²; esmalte 3,6 L ≈ 45 m²; massa corrida 25 kg ≈ 25-30 m² por demão; selador 18 L ≈ 200 m². Acrescente margem de 10% (superfície lisa) a 20% (textura/reboco). Use a Calculadora de Materiais do Assessor para montar embalagens e custo.`, ['cálculo', 'quantidade', 'rendimento', 'metragem', 'm²', 'litros', 'latas', 'embalagem']);
  add('kb_complementos', 'Lista de complementos para a venda', `Para pintar uma parede o cliente precisa, além da tinta: rolo de lã (lã baixa/antigota para superfície lisa; lã alta para textura/reboco), garfo e extensor; pincel/trincha 2" para recortes; bandeja com grade; fita crepe; lixa de parede (100/120 para massa, 150/180 antes da tinta, 220 para esmalte); espátula e desempenadeira (massa); lona plástica/papelão; pano e balde; EPI básico. Para madeira/metal: rolo de espuma, lixa fina, desengraxante, fundo anticorrosivo ou fundo para madeira, aguarrás (esmalte sintético). Ofereça sempre — é cuidado com o cliente e aumenta o ticket.`, ['complementos', 'rolo', 'pincel', 'lixa', 'fita', 'lona', 'bandeja', 'acessórios', 'ferramentas']);
  add('kb_massa', 'Massa corrida × massa acrílica', `Massa corrida (PVA): nivelamento em áreas internas secas. Massa acrílica: externo, banheiros, cozinhas e áreas úmidas (resiste à umidade ambiental), mas NÃO resolve infiltração ativa. Aplique camadas finas, deixe secar, lixe entre demãos e remova totalmente o pó antes de pintar. Massa não corrige infiltração, umidade ativa, base fraca nem movimentação estrutural.`, ['massa', 'corrida', 'acrílica', 'nivelamento']);
  add('kb_fundos', 'Selador, fundo preparador e primers', `Selador acrílico: reboco novo, massa, gesso, drywall e superfícies porosas — uniformiza a absorção e faz a tinta render. Fundo preparador de paredes: superfícies que soltam pó (calcinação, reboco fraco, tinta antiga degradada) — consolida a base. Fundo anticorrosivo (zarcão/primer para metal): obrigatório em ferro antes do esmalte. Primer para galvanizado/alumínio: metais não ferrosos (zarcão comum não adere). Fundo para madeira / isolante de tanino: madeira nova ou que mancha. Fundo bloqueador: manchas de umidade seca, nicotina, canetas. Pular o fundo é a causa nº 1 de retorno do cliente.`, ['selador', 'fundo', 'primer', 'zarcão', 'preparador', 'bloqueador']);
  add('kb_umidade', 'Umidade, infiltração e vazamento', `Sinais: manchas escuras ou amareladas, bolhas, pintura estufada, descascamento, sais esbranquiçados (eflorescência), reboco deteriorado, mofo recorrente. Perguntas: a mancha piora quando chove? Existe banheiro/cozinha/tubulação do outro lado? O problema começa no rodapé e sobe (capilaridade)? Já voltou depois de pintar? Com umidade ativa, "raspar + massa + tinta" NÃO resolve: a origem (infiltração, vazamento, impermeabilização, condensação) precisa ser corrigida antes. Oriente avaliação do profissional adequado e só depois venda o sistema de pintura (fundo + acabamento). Frase para o cliente: "A parede apresenta sinais compatíveis com umidade. Antes de refazer a pintura, precisamos identificar de onde ela vem."`, ['umidade', 'infiltração', 'vazamento', 'mancha', 'bolha', 'chuva', 'rodapé', 'capilaridade', 'sais']);
  add('kb_mofo', 'Mofo e bolor', `Mofo = pontos pretos/esverdeados em áreas úmidas e pouco ventiladas. Pintar por cima não resolve. Passos: identificar a causa (condensação, ventilação, infiltração) → tratar com solução anti-mofo (seguir o rótulo, usar EPI) → aguardar secar → preparar → pintar com tinta com fungicida/antimofo e acabamento lavável. Se a condição ambiental continuar, o mofo volta.`, ['mofo', 'bolor', 'fungo', 'antimofo', 'banheiro']);
  add('kb_descascamento', 'Descascamento e falhas de aderência', `Descubra qual camada está soltando: tinta sobre tinta (repintura sem lixar/brilho), tinta sobre massa (massa fraca ou pó), massa sobre reboco (base ruim) ou reboco deteriorado. Observe o verso do pedaço solto. Remova tudo sem aderência, corrija o substrato, lixe, aplique fundo e repinte. Nunca pinte por cima das partes soltas nem aplique massa para "segurar" tinta que está soltando. Superfície brilhante exige lixamento (fosqueamento) antes da nova tinta.`, ['descascamento', 'descascando', 'aderência', 'soltando', 'placas', 'lixar']);
  add('kb_superficies', 'Preparação por tipo de superfície (resumo da Tabela)', `Reboco novo: aguardar cura (~28 dias), limpar, selador, massa, tinta. Reboco antigo: raspar solto, fundo preparador se soltar pó, reparos, tinta. Massa corrida: lixar, tirar TODO o pó, selador/1ª demão diluída, tinta. Gesso: fundo/selador obrigatório (absorve muito). Drywall: tratar juntas, lixar, selador para uniformizar, tinta. Parede fosca pintada: limpar, testar aderência, reparos, tinta (fundo nos reparos). Parede brilhante/acetinada: lixar para fosquear, limpar, tinta. Esmalte antigo: lixar, desengordurar, esmalte. Madeira nova: lixar, fundo para madeira, esmalte ou verniz. Metal ferroso: tirar ferrugem, desengordurar, fundo anticorrosivo, esmalte. Galvanizado/alumínio: desengordurar, primer específico, esmalte. Mofo: tratar causa + descontaminar. Gordura: desengordurar ANTES de lixar. Pó: fundo preparador.`, ['superfície', 'reboco', 'gesso', 'drywall', 'madeira', 'metal', 'concreto', 'preparação', 'tabela']);
  add('kb_metal', 'Pintura de metal (portões, grades, esquadrias)', `Ferro/aço: remover toda a ferrugem (lixa/escova de aço/removedor), desengordurar, aplicar FUNDO ANTICORROSIVO e 2-3 demãos de esmalte sintético. Galvanizado e alumínio: desengordurar e usar PRIMER ESPECÍFICO para metais não ferrosos (zarcão comum não adere), depois esmalte. Nunca pinte sobre ferrugem ativa: ela continua crescendo sob a película e aparece em pontos alaranjados. Ferramentas: lixa 100/150 e 220, escova de aço, pincel de cerdas, rolo de espuma, aguarrás.`, ['metal', 'ferro', 'portão', 'grade', 'ferrugem', 'zarcão', 'galvanizado', 'alumínio', 'esmalte']);
  add('kb_madeira', 'Pintura de madeira', `Madeira nova: lixar no sentido das fibras, remover pó, fundo para madeira (ou isolante de tanino em madeiras que mancham), massa para madeira nas imperfeições, esmalte (cor) ou verniz/stain (natural), 2-3 demãos lixando entre elas (lixa 220). Madeira já pintada: remover o que está solto, lixar, fundo nas áreas expostas, acabamento compatível. Exterior: verniz marítimo ou stain com filtro solar. Madeira úmida ou apodrecida: não adianta acabamento — reparar/substituir primeiro. Manchas amareladas atravessando a tinta = tanino: use fundo bloqueador.`, ['madeira', 'verniz', 'stain', 'tanino', 'porta', 'deck']);
  add('kb_fachada', 'Pintura externa e fachadas', `Use tinta acrílica para exterior (proteção UV e antimofo); fachadas expostas pedem linha premium. Massa e fundo precisam ser acrílicos (nunca massa corrida PVA fora). Antes: lavar, tratar algas/mofo, corrigir fissuras, pingadeiras e rufos, verificar infiltração. Cores escuras esquentam e desbotam mais rápido no sol. Clima: não pinte com chuva prevista, sol forte direto, vento com poeira ou umidade alta; a obra só termina depois da cura.`, ['fachada', 'externa', 'exterior', 'muro', 'clima', 'chuva', 'sol']);
  add('kb_cores', 'Como ajudar o cliente a escolher cores', `Pergunte ambiente, luz (natural/artificial), móveis e sensação desejada. Cores claras ampliam; escuras aconchegam. Use a regra do catálogo: cor PRINCIPAL (paredes), SECUNDÁRIA (parede de destaque) e de APOIO (detalhes). Mostre 2 ou 3 combinações, não 10. Combinações coringa que combinam com quase tudo: Off-white + Sálvia + Madeira; Greige + Grafite + Branco; Bege + Terracota + Creme; Cinza + Azul Petróleo + Branco; Branco + Azul Marinho + Madeira. Sempre confirme nome e código no leque do fabricante e faça amostra — a foto do celular engana.`, ['cor', 'cores', 'combinação', 'catálogo', 'paleta', 'decoração']);
  add('kb_atendimento', 'Roteiro de atendimento Só Tintas', `1) Acolha e pergunte o projeto ("o que vai pintar?"). 2) Sondagem técnica: superfície, condição (pó, umidade, brilho, mofo), ambiente (interno seco/úmido/externo), tinta anterior, metragem. 3) Especifique o sistema: preparação → fundo → massa → acabamento, com número de demãos. 4) Calcule a quantidade com a Calculadora (demãos, rendimento, margem). 5) Ofereça os complementos (rolo, pincel, fita, lixa, lona). 6) Confirme cor e acabamento (anote código) e, se possível, amostra. 7) Feche com orientação de aplicação e convite para voltar com dúvidas. Honestidade: se a parede tem umidade ativa, diga que a tinta não resolve antes da causa.`, ['atendimento', 'venda', 'cliente', 'roteiro', 'sondagem', 'balcão']);
  add('kb_diagnostico', 'Diagnóstico rápido de defeitos (Atlas)', `A pintura está SOLTANDO? → descubra qual camada solta de qual (fichas 8-14): preparação, lixamento, fundo. Está MANCHADA? → umidade, contaminação, absorção, diluição, agentes biológicos (fichas 1-7, 20-21, 27, 36, 43-46). Está RACHANDO? → película, espessura, idade, compatibilidade, movimentação (fichas 18, 32, 49). Bolhas → umidade (1), calor/contaminação (13), madeira (38), metal (42). Pó na mão → calcinação (47)/pulverulenta (10). Marcas de rolo/pincel/emendas/escorrido → aplicação (22-30). Enrugou/amoleceu ao repintar → incompatibilidade (31, 34, 35). Sempre: observe → compare → investigue → corrija a causa → só então repinte.`, ['diagnóstico', 'defeito', 'problema', 'patologia', 'atlas']);
  add('kb_quando_nao_e_pintura', 'Quando o problema NÃO é de pintura', `Pare e recomende avaliação de outro profissional quando houver: vazamento ativo, infiltração, umidade intensa ou ascendente (rodapé), fissura relevante/recorrente, substrato severamente deteriorado, corrosão severa, madeira apodrecida, contaminação biológica extensa ou defeito que já voltou várias vezes. Semáforo: VERDE (imperfeições simples) → prepare e pinte; AMARELO (mancha sem origem, bolha sem causa, fissura pequena recorrente) → investigue; VERMELHO (vazamento, infiltração, corrosão severa) → corrija a causa antes. A tinta é a última camada: se o problema nasceu antes, trocar a última camada não resolve.`, ['não é pintura', 'vazamento', 'infiltração', 'fissura', 'estrutural', 'encaminhar']);
  add('kb_vistoria', 'Vistoria e orçamento: o que olhar antes de fechar', `Checklist de 5 minutos: umidade, infiltrações/vazamentos, aderência da pintura existente, fissuras, pó/esfarelamento, bolhas/descascamentos, mofo/contaminações, reparos anteriores, condição do substrato e histórico. Perguntas de histórico: quando foi pintada? Que problema teve? Houve infiltração/vazamento? Foi reparada? O problema voltou? Observe contra a luz, fotografe e classifique: A (adequada), B (precisa preparação — inclua no orçamento), C (investigar antes de pintar). Não orce só a pintura: orce a condição real da parede.`, ['vistoria', 'orçamento', 'checklist', 'ficha', 'classificação']);
  add('kb_ferramentas', 'Ferramentas e técnica de aplicação', `Rolo de lã baixa/antigota para paredes lisas; lã alta para texturas e reboco; rolo de espuma para esmalte em portas e metais; pincel/trincha para recortes. Mantenha o rolo bem carregado, pressão uniforme e passadas consistentes (carregar → distribuir → uniformizar). Não "esprema" o rolo nem repasse área já secando (marcas). Mantenha a borda molhada para evitar emendas. Faça recorte e rolo em sequência. Proteja piso, móveis e esquadrias com lona e fita crepe (retire a fita no tempo certo). Ferramentas limpas: resíduos contaminam a tinta.`, ['ferramenta', 'rolo', 'pincel', 'técnica', 'aplicação', 'emenda', 'marcas']);
  add('kb_cor_confirmacao', 'Confirmar cor antes de pintar', `Nunca confie em "aquele cinza" ou na foto do WhatsApp: tela, brilho, câmera e iluminação mudam a cor. Registre marca, linha, nome, código, acabamento e ambiente; faça amostra e peça confirmação do cliente. Mudança de cor depois de pintado é mudança solicitada, não defeito. Com mais de uma lata da mesma cor, misture/alterne para evitar diferença de lote.`, ['cor', 'confirmar', 'amostra', 'código', 'lote']);

  CONTEUDO.base_conhecimento = KB;
})();
